SELECT \"nct\", \"author\", \"year\", \"pubmed_id\", \"trial_phase\", \"treatment_regimen\", \"class_of_ici\", \"name_of_ici\", \"cancer_type\" FROM public.\"clinical_trials\" WHERE \"trial_phase\" = 'Phase 3' AND \"cancer_type\" = 'Colorectal' AND \"class_of_ici\" = 'PD1' AND \"monotherapy_combination\" = 'Monotherapy' AND \"type_of_combination\" = 'Monotherapy' AND \"type_of_therapy\" = 'Immunotherapy' AND \"is_pd_l1_positivity_inclusion_criteria\" = 'Yes';